def comps(Q,bg):
    H,W=len(Q),len(Q[0]); seen=[[False]*W for _ in range(H)]; out=[]
    for i in range(H):
        for j in range(W):
            if Q[i][j]!=bg and not seen[i][j]:
                st=[(i,j)]; seen[i][j]=True; c=[]
                while st:
                    y,x=st.pop(); c.append((y,x))
                    for dy,dx in((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<H and 0<=nx<W and Q[ny][nx]!=bg and not seen[ny][nx]:
                            seen[ny][nx]=True; st.append((ny,nx))
                out.append(c)
    return out
