       'BL':[[Di[H-h+i][j] for j in range(w)] for i in range(h)],'BR':[[Di[H-h+i][W-w+j] for j in range(W-w)] for i in range(h)]}
c=collections.defaultdict(collections.Counter)
for dn,(Di,O) in D.items():
