# Better: per-cell vote counting but using the fact each quadrant has DIFFERENT noise rates: weight each quadrant inversely proportional to noise.
def solve(Di,O_=None):
    Q=QD(Di); hh,ww=len(Q['TL']),len(Q['TL'][0])
    bgs={n:collections.Counter(sum(Q[n],[])).most_common(1)[0][0] for n in names}
    noises={n:sum(1 for row in Q[n] for v in row if v!=bgs[n]) for n in names}
    inv={n:1/(noises[n]+0.5) for n in names}
    out=[]
    for i in range(hh):
        row=[]
        for j in range(ww):
            vs=[int(Q[n][i][j]) for n in names]
            scores=collections.defaultdict(float)
            for p,n in enumerate(names):
                scores[vs[p]]+=inv[n]
            val,maxs=max(scores.items(),key=lambda kv:kv[1])
            row.append(int(val))
        out.append(row)
    return out
